          "하루 1~3회, 약면의 박리지(보호 비닐)를 벗기고 아픈 부위에 그대로 붙이면 돼요. 이 용법은 식약처 허가사항에 등록된 그대로예요. 붙이기 전에 땀이나 물기를 닦아 두면 접착이 오래가요.\n\n한 장을 붙였다가 다음 장으로 갈아 붙이는 식으로, 하루 세 번까지 쓸 수 있어요. 붙인 자리를 전기장판이나 온열기로 따뜻하게 하는 건 피하세요. 열이 더해지면 자극이 커질 수 있거든요. 그리고 5~6일 붙여도 증상이 나아지지 않으면 사용을 멈추고 약사와 상의하는 게 좋아요. 어린이가 쓸 때는 보호자가 붙여 주고 지켜봐 주세요. 정해진 용법과 용량을 지키는 게 기본이고, 깜빡했다고 여러 장을 한꺼번에 겹쳐 붙이지는 마세요.",
