        title: "이런 곳·이런 분은 붙이기 전에 확인하세요",
        content:
          "30개월 이하 유아, 습진이 있는 피부, 옻 등에 의한 피부염, 상처 난 부위에는 붙이면 안 돼요. 예외는 없어요. 이런 곳에 쓰면 자극이나 염증이 더 심해질 수 있거든요. 이 내용은 식약처 허가사항의 사용상 주의사항 항목에 그대로 실려 있어요.\n\n습윤하거나 미란(짓무름)이 심한 피부, 알레르기 체질인 분, 다른 병으로 치료를 받고 있는 분, 임신 중이거나 임신 가능성이 있는 여성, 수유부는 붙이기 전에 약사나 의사와 먼저 상의하세요. 소아가 쓸 때도 보호자가 함께 살펴야 하고요. 보관은 습기와 빛을 피해 실온에 두고, 어린이 손이 닿지 않는 곳에 두세요. 다른 약을 함께 쓰고 있다면 그 사실도 약사에게 미리 알려 주는 편이 안전해요. 마지막 판단은 늘 약사·의사와 함께 정하는 게 가장 안전해요.",
