        content:
          "붙인 자리가 붉어지거나 발진, 가려움, 화끈거리는 작열감이 나타날 수 있어요. 접촉피부염이 생기기도 하고요. 이런 증상이 보이면 바로 사용을 멈추는 게 원칙이에요. 무리하지 마세요.\n\n드물지만 천식발작을 부를 수도 있어요. 붙인 뒤 몇 시간 안에 숨을 쌕쌕거리거나 거품 같은 숨소리, 호흡곤란 같은 초기 증상이 오면 즉시 떼고 중단해야 해요. 천식발작은 부착 후 수시간 내에 나타나는 걸로 알려져 있어서, 처음 붙인 날은 몸 상태를 좀 더 살펴보는 게 좋아요. 특히 아스피린 천식이 있던 분은 이 반응 위험이 더 커요.\n\n피부감염을 동반한 염증 자리에 사용하면 감염이 겉으로 드러나지 않게 가려질 수 있어요. 그래서 감염이 있는 염증 부위라면 항균제나 항진균제 치료를 함께 받아야 한다고 허가사항에 나와 있어요. 이상 반응이 낫지 않고 계속되면 사용을 멈추고 약사와 상의하는 게 안전해요.",
