        content: "신신 에어파스의 주성분은 멘톨(Menthol), dl-캠퍼(dl-Camphor), 살리실산메틸(Methyl salicylate)이에요. 이 세 가지 성분이 스프레이 형태로 분사되어 빠르게 작용해요.\n\n에어파스는 분사 시 용매가 빠르게 기화하면서 강력한 냉각 효과를 줘요. 멘톨의 쿨링 효과와 기화열에 의한 물리적 냉각이 합쳐져서 붙이는 파스보다 더 시원한 느낌을 받을 수 있어요.\n\n첨가제로는 에탄올(용매), 프로판·부탄(분사제) 등이 포함돼요. 에탄올은 약물을 녹이고 빠르게 기화시키는 역할을 하고, 프로판·부탄은 스프레이 분사를 가능하게 하는 추진제예요.",
