          "가장 큰 특징은 크기예요. 손가락이나 발가락 같은 작은 관절에 딱 맞게 나온 소형 플라스타거든요. 식약처 허가사항에도 이 소형 규격이 별도 품목으로 등재되어 있어요. 한 통에 60매가 들어 있어 대용량이고요. 넓은 등이나 허벅지를 덮는 큰 파스와 달리, 좁고 구부러지는 부위에 잘 붙는 게 장점이에요.\n\n손가락 마디나 발가락처럼 자주 움직이는 곳은 큰 파스가 겉돌기 쉬워요. 작은 크기라 접히거나 떨어질 걱정이 덜하죠. 자잘한 관절 통증이 잦은 분이라면 낱장으로 편하게 쓰기 좋아요. 여러 부위를 돌아가며 붙여야 하는 분들도 매수가 넉넉해 자주 새로 사지 않아도 되는 편이에요. 큰 파스 한 장을 손가락에 맞게 잘라 쓰기보다, 처음부터 작게 나온 제품을 고르는 편이 붙이고 떼기도 훨씬 간편해요. 휴대도 가벼워요.",
