          "현대물파스에프는 삠·타박상·근육통·관절통 같은 통증에 발라 진통과 소염을 함께 돕는 바르는 물파스예요. 골절통, 요통, 어깨결림, 신경통, 류마티스 통증에도 쓰고요. 통증에만 쓰는 것도 아니에요. 피부 가려움, 벌레 물린 데, 추위로 손발이 트고 붉어진 동창에도 발라요. 적응증 범위가 꽤 넓어요.\n\n발랐을 때 화하게 시원한 느낌이 도는 건 살리실산메틸이 피부에서 청량감을 내며 부어오른 자리를 달래 주기 때문이죠. 운동 뒤 뻐근한 근육, 삔 발목, 오래 앉아 결린 어깨처럼 일상에서 자주 겪는 통증이 주요 대상이에요. 다만 부위가 심하게 부었거나 화끈거릴 때는 문질러 바르기보다 살짝 얹듯 도포하는 편이 나아요. 이 적응증들은 식약처 허가사항에 그대로 실려 있어요.",
