          "플루르비프로펜이라는 성분이 통증을 잡아요. 비스테로이드성 소염진통제(NSAIDs) 계열이라, 몸에서 통증과 염증을 만드는 물질이 생기는 걸 막아 붓기와 아픔을 줄여줘요. 이 성분을 얇은 첩부제(플라스타) 형태에 담아 피부로 스며들게 만든 게 이 제품이에요.\n\n만든 곳은 녹십자이고, 식약처 허가사항에 품목번호 202001573으로 등록된 일반의약품이에요. 처방전 없이 약국에서 살 수 있는 파스라는 뜻이죠. 허가사항 갱신일은 2020년 3월 6일로 등록돼 있고, 이 정보는 2026년 4월 5일 기준 식약처 데이터로 확인했어요. 유효성분은 1종, 플루르비프로펜 하나예요. 식약처 분류상 진통·진양·수렴·소염제(분류코드 02640) 상품군에 속해요. 붙이는 제형이라 먹는 약보다 위장에 부담이 덜하다는 게 장점이에요. 대신 피부에 직접 닿는 만큼, 붙인 자리에 자극이나 발진이 생길 수 있다는 건 아래에서 따로 짚을게요.",
