          "수분을 머금은 카타플라스마 제형의 외용 진통소염제예요. 신신제약(주)이 만들고, 식약처에 일반의약품으로 등록돼 품목번호 200600308을 갖고 있어요. 흔히 냉파프라 부르는 시원한 계열 파스로, 겔처럼 촉촉한 습포가 피부에 밀착되면서 멘톨의 서늘한 청량감과 함께 진통·소염 작용이 시작돼요. 손에 묻어도 끈적임 없이 씻기는 편이라 다루기가 수월해요.\n\n뜨겁게 데우는 온파프와 달리 열을 식히는 쪽이라, 붓고 화끈거리는 초기 손상에 더 잘 맞아요. 만성적으로 뻐근한 결림보다는 방금 삐끗하거나 부딪힌 급성기에 손이 가는 이유죠. 이 약은 외용으로만 써요. 짧지만 중요한 원칙이에요. 붙이는 용도지 먹는 약이 아니라는 점은 꼭 기억해요. 겔이 마르기 전엔 옷에 눌리지 않게 살짝 시간을 두고 움직이는 편이 좋아요.",
